    public function contradictoryScopes(array $declaration): array
    {
        return [
            'file' => $declaration['file'],
            'line' => $declaration['line'],
            'identifier' => self::INVALID_SCOPE_IDENTIFIER,
            'symbol' => $declaration['symbol'],
